<?php
require_once __DIR__.'/lib.php';
$user=require_user(); $pdo=db(); $error=''; $order=null;
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $id=(int)($_POST['plan_id']??0);$s=$pdo->prepare("SELECT * FROM payment_plans WHERE id=? AND status='active'");$s->execute([$id]);$plan=$s->fetch();try{if(!$plan)throw new RuntimeException('套餐不存在。');if(get_setting('purchase_mode','link')!=='direct')throw new RuntimeException('直接支付未开启。');$no=date('YmdHis').strtoupper(bin2hex(random_bytes(6)));$resp=alipay_request('alipay.trade.precreate',['out_trade_no'=>$no,'total_amount'=>number_format((float)$plan['price'],2,'.',''),'subject'=>APP_NAME.'-'.$plan['name'],'timeout_express'=>'15m']);if(($resp['code']??'')!=='10000')throw new RuntimeException($resp['sub_msg']??$resp['msg']??'支付宝下单失败');$pdo->prepare("INSERT INTO payment_orders(order_no,user_id,plan_id,plan_name,amount,duration_days,status,qr_code,created_at,updated_at) VALUES(?,?,?,?,?,?,'pending',?,?,?)")->execute([$no,$user['id'],$plan['id'],$plan['name'],$plan['price'],$plan['duration_days'],$resp['qr_code'],now(),now()]);redirect('/pay.php?order='.rawurlencode($no));}catch(Throwable $e){$error=$e->getMessage();}}
if(isset($_GET['order'])){$s=$pdo->prepare('SELECT * FROM payment_orders WHERE order_no=? AND user_id=?');$s->execute([$_GET['order'],$user['id']]);$order=$s->fetch();}
$plans=$pdo->query("SELECT * FROM payment_plans WHERE status='active' ORDER BY price")->fetchAll();
?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>购买套餐 - <?=h(APP_NAME)?></title><link rel="stylesheet" href="/assets/style.css?v=20260728-pay-v1"></head><body><main class="container pay-page"><a class="button-link" href="/dashboard.php">返回用户中心</a><section class="hero-panel"><div class="hero-copy"><p class="eyebrow">Alipay</p><h1>购买订阅套餐</h1><p class="hero-desc">支付成功后自动升级或累加订阅时间。</p></div></section><?php if($error):?><div class="alert bad"><?=h($error)?></div><?php endif;?><?php if($order):?><section class="panel pay-order" data-pay-order="<?=h($order['order_no'])?>"><h2><?=h($order['plan_name'])?> · ￥<?=h($order['amount'])?></h2><?php if($order['status']==='paid'):?><div class="alert ok">支付成功，订阅时间已到账。</div><?php else:?><img src="https://api.qrserver.com/v1/create-qr-code/?size=260x260&data=<?=rawurlencode($order['qr_code'])?>" alt="支付宝付款二维码"><a class="primary" href="<?=h($order['qr_code'])?>">打开支付宝付款</a><p class="muted" data-pay-status>等待支付结果...</p><script>setInterval(async()=>{const r=await fetch('/payment_status.php?order=<?=rawurlencode($order['order_no'])?>');const j=await r.json();if(j.status==='paid')location.reload()},3000)</script><?php endif;?></section><?php else:?><section class="plan-grid"><?php foreach($plans as $plan):?><form method="post" class="panel plan-card"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="plan_id" value="<?=(int)$plan['id']?>"><h2><?=h($plan['name'])?></h2><strong class="plan-price">￥<?=h($plan['price'])?></strong><p><?= (int)$plan['duration_days']?> 天</p><button class="primary" type="submit">支付宝支付</button></form><?php endforeach;?></section><?php endif;?></main></body></html>
